#include <algorithm>
static ComPtr<ID3D12Resource> bench_texture(ID3D12Device* dev,ID3D12GraphicsCommandList* cmd,DXGI_FORMAT format,int channels,const std::array<float,4>& value,bool uav,std::vector<ComPtr<ID3D12Resource>>& keep) {
 D3D12_RESOURCE_DESC desc{};desc.Dimension=D3D12_RESOURCE_DIMENSION_TEXTURE2D;desc.Width=2560;desc.Height=1440;desc.DepthOrArraySize=desc.MipLevels=1;desc.Format=format;desc.SampleDesc.Count=1;desc.Flags=uav?D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS:D3D12_RESOURCE_FLAG_NONE;
 auto out=resource(dev,desc,D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_COPY_DEST);D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp{};UINT rows;UINT64 rowBytes,total;dev->GetCopyableFootprints(&desc,0,1,0,&fp,&rows,&rowBytes,&total);
 std::vector<float> row(2560*channels);for(int x=0;x<2560;x++)for(int c=0;c<channels;c++)row[x*channels+c]=value[c];auto packed=pack_pixels(row.data(),row.size(),format);auto up=resource(dev,buffer(total),D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);void* p=nullptr;D3D12_RANGE empty{0,0};check(up->Map(0,&empty,&p),"Map benchmark upload");memset(p,0,(size_t)total);for(int y=0;y<1440;y++)memcpy((char*)p+fp.Offset+y*fp.Footprint.RowPitch,packed.data(),packed.size());up->Unmap(0,nullptr);
 D3D12_TEXTURE_COPY_LOCATION src{};src.pResource=up.Get();src.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;src.PlacedFootprint=fp;D3D12_TEXTURE_COPY_LOCATION dst{};dst.pResource=out.Get();dst.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;cmd->CopyTextureRegion(&dst,0,0,0,&src,nullptr);transition(cmd,out.Get(),D3D12_RESOURCE_STATE_COPY_DEST,uav?D3D12_RESOURCE_STATE_UNORDERED_ACCESS:D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);keep.push_back(up);return out;
}
static void uav_order(ID3D12GraphicsCommandList* cmd) { D3D12_RESOURCE_BARRIER b{};b.Type=D3D12_RESOURCE_BARRIER_TYPE_UAV;b.UAV.pResource=nullptr;cmd->ResourceBarrier(1,&b); }
