 std::array<std::vector<double>,2> samples;double totalMs=0;for(int round=0;round<12;round++)for(int kernel=0;kernel<2;kernel++){int i=round*4+kernel*2;if(ts[i+1]<ts[i])throw std::runtime_error("Timestamp ordering failure");double ms=double(ts[i+1]-ts[i])*1000/double(frequency);totalMs+=ms;if(round>=2)samples[kernel].push_back(ms);}
 std::cout<<std::setprecision(9)<<"{\"adapter\":\"NVIDIA GeForce RTX 5070\",\"fixture\":\"product full-edited cache; isolated kernels, no NGX/NR/game\",\"width\":2560,\"height\":1440,\"warmups_per_kernel\":2,\"samples_per_kernel\":10,\"timestamp_frequency_hz\":"<<frequency<<",\"measured_gpu_total_ms_including_warmup\":"<<totalMs<<",\"fence_timeout_ms\":5000,\"fence_completed\":true,\"queue\":\"one own-process direct queue\",\"texture_format\":\"current/edited/output "<<(fmt=="rgba16"?"RGBA16_FLOAT":"RGBA32_FLOAT")<<", motion RG32_FLOAT, depth R32_FLOAT\",\"init\":\"full texture upload before timestamps; uniform linear baseline and synthetic full edited RGB, alpha1, depth0.5; all-zero full-resolution motion\",\"history\":\"2x20B/pixel full-edited/reference half records, default-heap UAV buffers, refreshed A then reproject A-to-B; global UAV ordering each dispatch\",\"timed\":\"Dispatch plus following global UAV barrier; excludes init/upload, allocation, pipeline/root binding, query resolution, fence wait\",\"kernels\":[";
 for(int kernel=0;kernel<2;kernel++){auto sorted=samples[kernel];std::sort(sorted.begin(),sorted.end());double median=(sorted[4]+sorted[5])/2;double p95=sorted[8]+.55*(sorted[9]-sorted[8]);if(kernel)std::cout<<",";std::cout<<"{\"name\":\""<<(kernel==0?"refresh":"reproject")<<"\",\"median_ms\":"<<median<<",\"p95_ms\":"<<p95<<",\"samples_ms\":[";for(int i=0;i<10;i++){if(i)std::cout<<",";std::cout<<samples[kernel][i];}std::cout<<"]}";}
 std::cout<<"]}"<<std::endl;return 0;
